sys_script_include.script:
var TaskUtilsCS = Class.create();
TaskUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getTasksForEvent: function() {
		var eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new TaskUtilsScriptInclude().getTasksForEvent(eventId));
    },

    isTaskOverdue: function() {
		var taskId = this.getParameter('sysparm_taskId');
        return JSON.stringify(new TaskUtilsScriptInclude().isTaskOverdue(taskId));
    },

    getTaskDetailsById: function() {
		var taskId = this.getParameter('sysparm_taskId');
        return JSON.stringify(new TaskUtilsScriptInclude().getTaskDetailsById(taskId));
    },

    getTasksByDueDate: function() {
		var dueDate = this.getParameter('sysparm_dueDate');
        return JSON.stringify(new TaskUtilsScriptInclude().getTasksByDueDate(dueDate));
    },

    type: 'TaskUtilsCS'
});
